import { createRequire } from "node:module";
import type * as Addon from "../../../index.js";

/** The native addon's exports (`bindings/node/index.d.ts`, generated by the napi CLI). */
export type NativeAddon = typeof Addon;
export type NativeTransport = Addon.NativeTransport;
export type NativeDispatcher = Addon.Dispatcher;

let loaded: NativeAddon | null | undefined;

/**
 * The Rust core, or `null` when it can't be used: no build for this platform, a bundler that hides
 * `import.meta.url`, or `LOGQUILL_NO_NATIVE` set. Every caller keeps a pure-JavaScript path for
 * that case, so a missing addon costs speed and nothing else.
 */
export function nativeAddon(): NativeAddon | null {
  if (loaded !== undefined) return loaded;
  loaded = null;
  if (process.env.LOGQUILL_NO_NATIVE) return loaded;
  try {
    const require = createRequire(import.meta.url);
    // from `sdk/src/core` in the repository, from `dist` once built
    for (const path of ["../../../index.js", "../index.js"]) {
      try {
        loaded = require(path) as NativeAddon;
        break;
      } catch {
        // try the next location
      }
    }
  } catch {
    // import.meta.url is unavailable (a CommonJS bundle without shims)
  }
  return loaded;
}

/**
 * `object` without its `undefined` fields. The addon's option objects have optional fields, and with
 * `exactOptionalPropertyTypes` an explicit `undefined` is not the same as leaving a field out.
 */
export function compact<T extends object>(object: T): { [K in keyof T]?: Exclude<T[K], undefined> } {
  return Object.fromEntries(
    Object.entries(object).filter(([, value]) => value !== undefined),
  ) as { [K in keyof T]?: Exclude<T[K], undefined> };
}

/**
 * The Rust core, for a feature that has no JavaScript fallback (the adaptive sampler, the flight
 * recorder, the run summary, the metrics backends, ...). Throws, saying what to do, when it can't be
 * loaded.
 */
export function requireNative(feature: string, member?: keyof NativeAddon): NativeAddon {
  const addon = nativeAddon();
  if (addon === null) {
    throw new Error(
      `${feature} needs the native addon, which could not be loaded — build it with \`npm run build\` ` +
        "in bindings/node, install the package for this platform, or unset LOGQUILL_NO_NATIVE",
    );
  }
  if (member !== undefined && addon[member] === undefined) {
    // the WebAssembly build has the core logic only: no worker, files, HTTP or metrics sinks
    throw new Error(
      `${feature} needs the native runtime (the worker thread, files, HTTP and metrics sinks), which the ` +
        "WebAssembly build does not include — install the native package for this platform",
    );
  }
  return addon;
}

const live = new Set<NativeDispatcher>();
let exitHookInstalled = false;

/**
 * Drains `dispatcher` when the process exits. Records sit in a Rust queue, so a script that ends
 * without calling `logger.close()` would otherwise lose whatever the worker has not written yet.
 * An `exit` handler cannot await, so this blocks, for at most five seconds.
 */
export function drainOnExit(dispatcher: NativeDispatcher): void {
  live.add(dispatcher);
  if (exitHookInstalled) return;
  exitHookInstalled = true;
  process.on("exit", () => {
    for (const each of live) each.flushSync(5000);
  });
}
